<script setup lang="ts">
import type {FloodForecast} from '../../../types/flood';import {floodLevelLabels} from '../../../types/flood';defineProps<{forecast:FloodForecast|null;error:string;loading:boolean;stale:boolean}>();
</script><template><section class="panel flood-forecast" data-testid="flood-forecast" :data-revision="forecast?.basedOnRevision??0"><h3>未来水位 <small>模型外推</small></h3><p v-if="error" role="alert">{{error}}</p><p v-else-if="!forecast">{{loading?'正在计算预测…':'等待预测'}}</p><template v-if="forecast"><div class="forecast-grid"><div v-for="p in forecast.points" :key="p.minute"><span>+{{p.minute}} min</span><strong>{{p.waterLevel.toFixed(1)}}<small>cm</small></strong><em>{{floodLevelLabels[p.riskLevel]}}</em></div></div><p v-if="forecast.points.length">{{forecast.points.at(-1)!.waterLevel>forecast.current.waterLevel?'↑ 上升':'↓ 下降或稳定'}} · 若降雨与设备演化趋势持续，预计 30 分钟后水位约 {{forecast.points.at(-1)!.waterLevel.toFixed(1)}} cm。</p><small>{{forecast.assumption}}</small><small v-if="stale" class="forecast-stale">实时连接已断开，保留上次预测</small></template></section></template>
